	ContextKeyExpr.equals(ResourceContextKey.LangId.key, 'python'),
	ContextKeyExpr.equals(ResourceContextKey.LangId.key, 'r'),
	ContextKeyExpr.equals(ResourceContextKey.LangId.key, 'julia'),
